package ink.warrant.instrument

import android.bluetooth.BluetoothGattCharacteristic
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.UUID

class TH08HumidityDriver : Driver {
    override val id: String = "th08_humidity"
    override val label: String = "TH-08 Humidity"
    override val produces: Produces = Produces(
        unit = "%%",
        min = 0.0,
        max = 100.0
    )

    override val matches: Match = Match(
        serviceUuids = listOf(sig(0x181a)),
        namePrefixes = listOf("TH-08")
    )

    override fun characteristicFor(services: List<UUID>): CharacteristicRef? {
        val serviceUuid = sig(0x181a)
        val charUuid = sig(0x2a6f)
        return if (services.contains(serviceUuid)) {
            CharacteristicRef(serviceUuid, charUuid)
        } else {
            null
        }
    }

    override fun decode(raw: ByteArray): Double? {
        if (raw.size < 2) return null
        val rawValue = ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).short.toInt() and 0xFFFF
        return rawValue / 100.0
    }
}

